     1→/**
     2→ * CLAUDELang v6.0 Compiler
     3→ * CLAUDELang JSON → VT 바이트코드 변환
     4→ */
     5→
     6→class CLAUDELangCompiler {
     7→  constructor() {
     8→    this.scope = new Map(); // 변수 저장소
     9→    this.vtFunctions = new Map(); // VT 함수 목록
    10→    this.initializeVTFunctions();
    11→  }
    12→
    13→  /**
    14→   * VT 함수 목록 초기화
    15→   */
    16→  initializeVTFunctions() {
    17→    // HTTP (예)
    18→    this.registerFunction("HTTP.get", ["url: string"], "Object");
    19→    this.registerFunction("HTTP.post", ["url: string", "data: Object"], "Object");
    20→
    21→    // Array
    22→    this.registerFunction("Array.map", ["array: Array", "fn: Function"], "Array");
    23→    this.registerFunction("Array.filter", ["array: Array", "fn: Function"], "Array");
    24→    this.registerFunction("Array.reduce", ["array: Array", "fn: Function", "init: any"], "any");
    25→    this.registerFunction("Array.find", ["array: Array", "fn: Function"], "any");
    26→
    27→    // String
    28→    this.registerFunction("String.split", ["str: string", "delimiter: string"], "Array<string>");
    29→    this.registerFunction("String.join", ["arr: Array", "delimiter: string"], "string");
    30→    this.registerFunction("String.upper", ["str: string"], "string");
    31→    this.registerFunction("String.lower", ["str: string"], "string");
    32→    this.registerFunction("String.trim", ["str: string"], "string");
    33→
    34→    // Math
    35→    this.registerFunction("Math.sqrt", ["x: f64"], "f64");
    36→    this.registerFunction("Math.pow", ["x: f64", "y: f64"], "f64");
    37→    this.registerFunction("Math.abs", ["x: f64"], "f64");
    38→
    39→    // FileSystem
    40→    this.registerFunction("FS.read", ["path: string"], "string");
    41→    this.registerFunction("FS.write", ["path: string", "content: string"], "bool");
    42→    this.registerFunction("FS.exists", ["path: string"], "bool");
    43→
    44→    // JSON
    45→    this.registerFunction("JSON.parse", ["str: string"], "Object");
    46→    this.registerFunction("JSON.stringify", ["obj: Object"], "string");
    47→
    48→    // Markdown
    49→    this.registerFunction("Markdown.create", [], "Object");
    50→    this.registerFunction("Markdown.heading", ["doc: Object", "level: i32", "text: string"], "Object");
    51→    this.registerFunction("Markdown.paragraph", ["doc: Object", "text: string"], "Object");
    52→    this.registerFunction("Markdown.code", ["doc: Object", "lang: string", "code: string"], "Object");
    53→    this.registerFunction("Markdown.build", ["doc: Object"], "string");
    54→
    55→    // Notion
    56→    this.registerFunction("Notion.post", ["data: Object"], "Object");
    57→    this.registerFunction("Notion.query", ["database_id: string", "filter: Object"], "Array");
    58→
    59→    // Print (기본)
    60→    this.registerFunction("print", ["value: any"], "null");
    61→  }
    62→
    63→  registerFunction(name, params, returnType) {
    64→    this.vtFunctions.set(name, {
    65→      params: params,
    66→      returnType: returnType,
    67→    });
    68→  }
    69→
    70→  /**
    71→   * 주요 컴파일 함수
    72→   */
    73→  compile(claudelangJson) {
    74→    try {
    75→      // 1. 검증
    76→      this.validate(claudelangJson);
    77→
    78→      // 2. 타입 검사
    79→      this.typeCheck(claudelangJson);
    80→
    81→      // 3. VT 코드 생성
    82→      const vtCode = this.generateVTCode(claudelangJson);
    83→
    84→      return {
    85→        success: true,
    86→        code: vtCode,
    87→        errors: [],
    88→      };
    89→    } catch (error) {
    90→      return {
    91→        success: false,
    92→        code: null,
    93→        errors: [error.message],
    94→      };
    95→    }
    96→  }
    97→
    98→  /**
    99→   * 스키마 검증
   100→   */
   101→  validate(obj) {
   102→    if (!obj.version) {
   103→      throw new Error("Missing 'version' field");
   104→    }
   105→
   106→    if (obj.version !== "6.0") {
   107→      throw new Error(`Unsupported version: ${obj.version}`);
   108→    }
   109→
   110→    if (!Array.isArray(obj.instructions)) {
   111→      throw new Error("'instructions' must be an array");
   112→    }
   113→
   114→    obj.instructions.forEach((instr, idx) => {
   115→      if (!instr.type) {
   116→        throw new Error(`Instruction at line ${idx} missing 'type'`);
   117→      }
   118→
   119→      switch (instr.type) {
   120→        case "var":
   121→          if (!instr.name || !instr.value_type) {
   122→            throw new Error(`VarDeclaration at line ${idx} missing required fields`);
   123→          }
   124→          break;
   125→
   126→        case "call":
   127→          if (!instr.function || !Array.isArray(instr.args)) {
   128→            throw new Error(`CallInstruction at line ${idx} missing required fields`);
   129→          }
   130→          break;
   131→
   132→        case "condition":
   133→          if (!instr.test || !Array.isArray(instr.then)) {
   134→            throw new Error(`ConditionInstruction at line ${idx} missing required fields`);
   135→          }
   136→          break;
   137→
   138→        case "loop":
   139→          if (!instr.iterator || !instr.range || !Array.isArray(instr.body)) {
   140→            throw new Error(`LoopInstruction at line ${idx} missing required fields`);
   141→          }
   142→          break;
   143→
   144→        case "comment":
   145→          break;
   146→
   147→        default:
   148→          throw new Error(`Unknown instruction type at line ${idx}: ${instr.type}`);
   149→      }
   150→    });
   151→  }
   152→
   153→  /**
   154→   * 타입 검사
   155→   */
   156→  typeCheck(ast) {
   157→    this.scope.clear();
   158→
   159→    ast.instructions.forEach((instr, idx) => {
   160→      try {
   161→        this.checkInstruction(instr);
   162→      } catch (error) {
   163→        throw new Error(`Type error at instruction ${idx}: ${error.message}`);
   164→      }
   165→    });
   166→  }
   167→
   168→  checkInstruction(instr) {
   169→    switch (instr.type) {
   170→      case "var":
   171→        // 변수를 scope에 추가
   172→        this.scope.set(instr.name, instr.value_type);
   173→
   174→        // 초기값 타입이 있으면 검사
   175→        if (instr.value !== undefined && typeof instr.value === "object" && instr.value.type) {
   176→          const exprType = this.inferType(instr.value);
   177→          if (!this.isCompatible(exprType, instr.value_type)) {
   178→            throw new Error(
   179→              `Cannot assign ${exprType} to ${instr.value_type}`
   180→            );
   181→          }
   182→        }
   183→        break;
   184→
   185→      case "call":
   186→        // 함수 존재 여부 확인
   187→        if (!this.vtFunctions.has(instr.function)) {
   188→          throw new Error(`Unknown function: ${instr.function}`);
   189→        }
   190→
   191→        // 함수 시그니처 검사
   192→        const signature = this.vtFunctions.get(instr.function);
   193→        if (instr.args.length !== signature.params.length) {
   194→          throw new Error(
   195→            `${instr.function} expects ${signature.params.length} arguments, got ${instr.args.length}`
   196→          );
   197→        }
   198→
   199→        // 반환값을 scope에 추가
   200→        if (instr.assign_to) {
   201→          this.scope.set(instr.assign_to, signature.returnType);
   202→        }
   203→        break;
   204→
   205→      case "condition":
   206→        // 조건 검사 (선택사항)
   207→        break;
   208→
   209→      case "loop":
   210→        // 범위 검사 (선택사항)
   211→        break;
   212→    }
   213→  }
   214→
   215→  inferType(expr) {
   216→    if (!expr) {
   217→      return "any";
   218→    }
   219→
   220→    // 기본 값 타입
   221→    if (typeof expr === "number") {
   222→      return "i32";
   223→    }
   224→    if (typeof expr === "string") {
   225→      return "string";
   226→    }
   227→    if (typeof expr === "boolean") {
   228→      return "bool";
   229→    }
   230→
   231→    if (expr.type === "literal") {
   232→      return expr.value_type || "any";
   233→    } else if (expr.type === "ref") {
   234→      if (!this.scope.has(expr.name)) {
   235→        // throw new Error(`Undefined variable: ${expr.name}`);
   236→        return "any"; // 선언되지 않은 변수는 any로 취급
   237→      }
   238→      return this.scope.get(expr.name);
   239→    } else if (expr.type === "arithmetic") {
   240→      return "f64"; // 간단한 추론
   241→    } else if (expr.type === "comparison") {
   242→      return "bool";
   243→    } else if (expr.type === "array") {
   244→      return "Array<any>";
   245→    } else if (expr.type === "object") {
   246→      return "Object";
   247→    } else if (expr.type === "lambda") {
   248→      return "Function";
   249→    } else if (expr.type === "call") {
   250→      if (this.vtFunctions.has(expr.function)) {
   251→        return this.vtFunctions.get(expr.function).returnType;
   252→      }
   253→      return "any";
   254→    }
   255→
   256→    return "any";
   257→  }
   258→
   259→  isCompatible(from, to) {
   260→    if (from === to) return true;
   261→    if (from === "any" || to === "any") return true;
   262→    if (from === "i32" && to === "f64") return true; // 정수 → 실수
   263→    return false;
   264→  }
   265→
   266→  /**
   267→   * VT 코드 생성
   268→   */
   269→  generateVTCode(ast) {
   270→    const lines = [
   271→      "; CLAUDELang v6.0 compiled to VT",
   272→      "; Generated code below",
   273→      "",
   274→    ];
   275→
   276→    ast.instructions.forEach((instr) => {
   277→      lines.push(this.generateInstruction(instr));
   278→    });
   279→
   280→    return lines.filter((line) => line !== null).join("\n");
   281→  }
   282→
   283→  generateInstruction(instr) {
   284→    switch (instr.type) {
   285→      case "var":
   286→        return this.generateVarDeclaration(instr);
   287→
   288→      case "call":
   289→        return this.generateCallInstruction(instr);
   290→
   291→      case "condition":
   292→        return this.generateConditionInstruction(instr);
   293→
   294→      case "loop":
   295→        return this.generateLoopInstruction(instr);
   296→
   297→      case "comment":
   298→        return `; ${instr.text}`;
   299→
   300→      default:
   301→        return null;
   302→    }
   303→  }
   304→
   305→  generateVarDeclaration(instr) {
   306→    let value;
   307→
   308→    // 값이 기본 타입(숫자, 문자열, 불린)이면 직접 처리
   309→    if (typeof instr.value === "number") {
   310→      value = instr.value.toString();
   311→    } else if (typeof instr.value === "string") {
   312→      value = `"${instr.value}"`;
   313→    } else if (typeof instr.value === "boolean") {
   314→      value = instr.value ? "true" : "false";
   315→    } else if (typeof instr.value === "object" && instr.value) {
   316→      // 객체/배열이면 표현식으로 처리
   317→      value = this.generateExpression(instr.value);
   318→    } else {
   319→      value = "null";
   320→    }
   321→
   322→    return `(define ${instr.name} ${value})`;
   323→  }
   324→
   325→  generateCallInstruction(instr) {
   326→    const args = instr.args.map((arg) => this.generateExpression(arg)).join(" ");
   327→    const callCode = `(call ${instr.function} ${args})`;
   328→
   329→    if (instr.assign_to) {
   330→      return `(define ${instr.assign_to} ${callCode})`;
   331→    } else {
   332→      return callCode;
   333→    }
   334→  }
   335→
   336→  generateExpression(expr) {
   337→    if (!expr) {
   338→      return "null";
   339→    }
   340→
   341→    // 기본 타입 처리
   342→    if (typeof expr === "number" || typeof expr === "boolean") {
   343→      return expr.toString();
   344→    }
   345→    if (typeof expr === "string") {
   346→      return `"${expr}"`;
   347→    }
   348→
   349→    // 객체/배열 타입 처리
   350→    if (typeof expr !== "object" || !expr.type) {
   351→      return "null";
   352→    }
   353→
   354→    switch (expr.type) {
   355→      case "literal":
   356→        if (expr.value_type === "string") {
   357→          return `"${expr.value}"`;
   358→        }
   359→        return expr.value !== undefined ? expr.value.toString() : "null";
   360→
   361→      case "ref":
   362→        return expr.name;
   363→
   364→      case "arithmetic":
   365→        const left = this.generateExpression(expr.left);
   366→        const right = this.generateExpression(expr.right);
   367→        return `(${expr.operator} ${left} ${right})`;
   368→
   369→      case "comparison":
   370→        const compLeft = this.generateExpression(expr.left);
   371→        const compRight = this.generateExpression(expr.right);
   372→        return `(${expr.operator} ${compLeft} ${compRight})`;
   373→
   374→      case "array":
   375→        if (!expr.elements || expr.elements.length === 0) {
   376→          return "(array)";
   377→        }
   378→        const elements = expr.elements
   379→          .map((e) => this.generateExpression(e))
   380→          .join(" ");
   381→        return `(array ${elements})`;
   382→
   383→      case "object":
   384→        const props = Object.entries(expr.properties)
   385→          .map(([key, value]) => `("${key}" ${this.generateExpression(value)})`)
   386→          .join(" ");
   387→        return `(object ${props})`;
   388→
   389→      case "lambda":
   390→        const params = expr.params ? expr.params.map((p) => p.name).join(" ") : "";
   391→        const bodyExpr = expr.body
   392→          .map((b) => this.generateInstruction(b))
   393→          .filter((b) => b !== null)
   394→          .join(" ");
   395→        return `(fn (${params}) ${bodyExpr})`;
   396→
   397→      case "property":
   398→        const obj = this.generateExpression(expr.object);
   399→        return `(property ${obj} "${expr.property}")`;
   400→
   401→      case "index":
   402→        const array = this.generateExpression(expr.array);
   403→        const index = this.generateExpression(expr.index);
   404→        return `(index ${array} ${index})`;
   405→
   406→      default:
   407→        return "null";
   408→    }
   409→  }
   410→
   411→  generateConditionInstruction(instr) {
   412→    const test = this.generateExpression(instr.test);
   413→    const thenCode = instr.then
   414→      .map((i) => this.generateInstruction(i))
   415→      .filter((i) => i !== null)
   416→      .join(" ");
   417→    const elseCode = instr.else
   418→      ? instr.else
   419→          .map((i) => this.generateInstruction(i))
   420→          .filter((i) => i !== null)
   421→          .join(" ")
   422→      : "null";
   423→
   424→    return `(if ${test} (do ${thenCode}) (do ${elseCode}))`;
   425→  }
   426→
   427→  generateLoopInstruction(instr) {
   428→    const range = this.generateExpression(instr.range);
   429→    const body = instr.body
   430→      .map((i) => this.generateInstruction(i))
   431→      .filter((i) => i !== null)
   432→      .join(" ");
   433→
   434→    return `(for ${instr.iterator} ${range} (do ${body}))`;
   435→  }
   436→}
