  runner.assertIncludes(result.code, "(fn", "람다 함수 없음");
  runner.assertIncludes(result.code, "(>", "비교 연산 없음");
});

// ====== Test 8: String.split ======
runner.test("Test 8: String.split 호출", () => {
  const program = {
    version: "6.0",
    instructions: [
      {
        type: "var",
