          operator: ">=",
          left: { type: "ref", name: "score" },
          right: { type: "literal", value_type: "i32", value: 90 },
        },
        then: [
          {
            type: "call",
            function: "print",
            args: [
              { type: "literal", value_type: "string", value: "A" },
            ],
          },
        ],
        else: [
          {
